      "director": "Agnès Varda",
      "year": 1968,
      "duration": 28,
      "poster": "https://a.ltrbxd.com/resized/film-poster/1/0/9/7/9/1/109791-black-panthers-0-500-0-750-crop.jpg?v=d430b2c305",
